import { SyncedStateServer } from "rwsdk/use-synced-state/worker";

export class CustomSyncedStateServer extends SyncedStateServer {
  constructor(ctx: any, env: any) {
    super(ctx, env);

    // Load persisted state into the in-memory store on startup
    this.ctx.blockConcurrencyWhile(async () => {
      try {
        const stored = await this.ctx.storage.list();
        for (const [key, value] of stored.entries()) {
          // Use super.setState to populate the in-memory map of the base class
          super.setState(value, key);
        }
      } catch (err) {
        console.error("Error loading persisted state:", err);
      }
    });
  }

  override setState(value: any, key: string): void {
    // Call super.setState to update the in-memory map and notify subscribers
    super.setState(value, key);

    // Persist the state change to local Cloudflare-backed durable storage
    this.ctx.storage.put(key, value).catch((err: any) => {
      console.error(`Failed to persist key ${key}:`, err);
    });

    // Intercept isRunning changes to start/stop the tick producer
    if (key === "isRunning") {
      if (value === true) {
        this.startProducer();
      } else {
        this.stopProducer();
      }
    }
  }

  private startProducer(): void {
    // Schedule an alarm in 1 second
    this.ctx.storage.setAlarm(Date.now() + 1000);
  }

  private stopProducer(): void {
    this.ctx.storage.deleteAlarm();
  }

  async alarm(): Promise<void> {
    const isRunning = this.getState("isRunning");
    if (!isRunning) {
      return;
    }

    // 1. Increment sequence number (seq starts at 1)
    const currentSeq = (this.getState("seq") as number) || 0;
    const nextSeq = currentSeq + 1;
    this.setState(nextSeq, "seq");

    // 2. Generate random value in range 1..100 inclusive
    const value = Math.floor(Math.random() * 100) + 1;
    this.setState(value, "currentValue");

    // 3. Update running tick count
    const tickCount = (this.getState("tickCount") as number || 0) + 1;
    this.setState(tickCount, "tickCount");

    // 4. Update running min and max values
    const currentMin = this.getState("minValue") as number | null;
    const currentMax = this.getState("maxValue") as number | null;
    const nextMin = (currentMin === null || currentMin === undefined) ? value : Math.min(currentMin, value);
    const nextMax = (currentMax === null || currentMax === undefined) ? value : Math.max(currentMax, value);
    this.setState(nextMin, "minValue");
    this.setState(nextMax, "maxValue");

    // 5. Check threshold and alert count
    const threshold = this.getState("threshold") as number | null;
    let isAlert = false;
    if (threshold !== null && threshold !== undefined && threshold !== "") {
      if (value > Number(threshold)) {
        isAlert = true;
        const alertCount = (this.getState("alertCount") as number || 0) + 1;
        this.setState(alertCount, "alertCount");
      }
    }

    // 6. Append to history (retain at least 50 most recent ticks)
    const history = (this.getState("history") as any[]) || [];
    const newTick = { seq: nextSeq, value, alert: isAlert };
    let nextHistory = [newTick, ...history];
    if (nextHistory.length > 100) { // Keep up to 100 to be safe, but at least 50
      nextHistory = nextHistory.slice(0, 50);
    }
    this.setState(nextHistory, "history");

    // 7. Schedule next alarm in 1 second (roughly 1 tick per second)
    this.ctx.storage.setAlarm(Date.now() + 1000);
  }
}

"use client";

import React, { useState, useEffect } from "react";
import { useSyncedState } from "rwsdk/use-synced-state/client";

interface Tick {
  seq: number;
  value: number;
  alert: boolean;
}

export function MetricsPage() {
  const [isRunning, setIsRunning] = useSyncedState<boolean>(false, "isRunning");
  const [currentValue, setCurrentValue] = useSyncedState<number | null>(null, "currentValue");
  const [tickCount, setTickCount] = useSyncedState<number>(0, "tickCount");
  const [minValue, setMinValue] = useSyncedState<number | null>(null, "minValue");
  const [maxValue, setMaxValue] = useSyncedState<number | null>(null, "maxValue");
  const [alertCount, setAlertCount] = useSyncedState<number>(0, "alertCount");
  const [threshold, setThreshold] = useSyncedState<number | null>(null, "threshold");
  const [history, setHistory] = useSyncedState<Tick[]>([], "history");

  const [inputValue, setInputValue] = useState<string>("");

  // Sync the local input value with the active threshold when it changes on the server
  useEffect(() => {
    if (threshold !== null && threshold !== undefined) {
      setInputValue(threshold.toString());
    }
  }, [threshold]);

  const handleApplyThreshold = () => {
    const val = inputValue.trim();
    if (val === "") {
      setThreshold(null);
    } else {
      const num = Number(val);
      if (!isNaN(num)) {
        setThreshold(num);
      }
    }
  };

  const isOver = currentValue !== null && threshold !== null && threshold !== undefined && threshold !== "" && currentValue > Number(threshold);

  return (
    <div style={{ padding: "20px", fontFamily: "sans-serif" }}>
      <h1>Live Metrics Dashboard</h1>

      {/* Controls */}
      <div style={{ marginBottom: "20px", display: "flex", gap: "10px", alignItems: "center" }}>
        <button
          data-testid="start-stream"
          onClick={() => setIsRunning(true)}
          disabled={isRunning}
          style={{ padding: "8px 16px", cursor: "pointer" }}
        >
          Start Stream
        </button>
        <button
          data-testid="stop-stream"
          onClick={() => setIsRunning(false)}
          disabled={!isRunning}
          style={{ padding: "8px 16px", cursor: "pointer" }}
        >
          Stop Stream
        </button>
        <div style={{ marginLeft: "20px", display: "flex", gap: "5px", alignItems: "center" }}>
          <label htmlFor="threshold-input">Threshold:</label>
          <input
            id="threshold-input"
            type="number"
            data-testid="threshold-input"
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            style={{ padding: "6px", width: "100px" }}
          />
          <button
            data-testid="apply-threshold"
            onClick={handleApplyThreshold}
            style={{ padding: "8px 16px", cursor: "pointer" }}
          >
            Apply Threshold
          </button>
        </div>
      </div>

      {/* Status */}
      <div style={{ marginBottom: "20px" }}>
        Status: <strong>{isRunning ? "Running" : "Stopped"}</strong>
        {threshold !== null && threshold !== undefined && threshold !== "" && (
          <span style={{ marginLeft: "20px" }}>
            Active Threshold: <strong>{threshold}</strong>
          </span>
        )}
      </div>

      {/* Widgets Grid */}
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(150px, 1fr))", gap: "15px", marginBottom: "30px" }}>
        <div style={{ border: "1px solid #ccc", padding: "15px", borderRadius: "4px", backgroundColor: isOver ? "#ffebee" : "#f9f9f9" }}>
          <h3>Latest Value</h3>
          <div
            data-testid="current-value"
            {...(isOver ? { "data-over": "true" } : {})}
            style={{ fontSize: "2rem", fontWeight: "bold", color: isOver ? "#c62828" : "#333" }}
          >
            {currentValue !== null ? currentValue : "-"}
          </div>
        </div>

        <div style={{ border: "1px solid #ccc", padding: "15px", borderRadius: "4px", backgroundColor: "#f9f9f9" }}>
          <h3>Tick Count</h3>
          <div data-testid="tick-count" style={{ fontSize: "2rem", fontWeight: "bold" }}>
            {tickCount}
          </div>
        </div>

        <div style={{ border: "1px solid #ccc", padding: "15px", borderRadius: "4px", backgroundColor: "#f9f9f9" }}>
          <h3>Min Value</h3>
          <div data-testid="min-value" style={{ fontSize: "2rem", fontWeight: "bold" }}>
            {minValue !== null ? minValue : "-"}
          </div>
        </div>

        <div style={{ border: "1px solid #ccc", padding: "15px", borderRadius: "4px", backgroundColor: "#f9f9f9" }}>
          <h3>Max Value</h3>
          <div data-testid="max-value" style={{ fontSize: "2rem", fontWeight: "bold" }}>
            {maxValue !== null ? maxValue : "-"}
          </div>
        </div>

        <div style={{ border: "1px solid #ccc", padding: "15px", borderRadius: "4px", backgroundColor: "#f9f9f9" }}>
          <h3>Alert Count</h3>
          <div data-testid="alert-count" style={{ fontSize: "2rem", fontWeight: "bold", color: alertCount > 0 ? "#c62828" : "#333" }}>
            {alertCount}
          </div>
        </div>
      </div>

      {/* Scrolling History */}
      <h2>Tick History</h2>
      <div
        data-testid="history"
        style={{
          border: "1px solid #ccc",
          borderRadius: "4px",
          maxHeight: "300px",
          overflowY: "auto",
          padding: "10px",
          backgroundColor: "#fff",
        }}
      >
        {history.length === 0 ? (
          <div style={{ color: "#888", fontStyle: "italic" }}>No ticks emitted yet.</div>
        ) : (
          history.map((tick) => {
            const isAlert = tick.alert;
            const extraAttrs = isAlert ? { "data-alert": "true" } : {};
            return (
              <div
                key={tick.seq}
                data-testid={`tick-${tick.seq}`}
                data-seq={tick.seq}
                data-value={tick.value}
                {...extraAttrs}
                style={{
                  padding: "8px 12px",
                  borderBottom: "1px solid #eee",
                  backgroundColor: isAlert ? "#ffebee" : "transparent",
                  color: isAlert ? "#c62828" : "#333",
                  fontWeight: isAlert ? "bold" : "normal",
                  display: "flex",
                  justifyContent: "space-between",
                }}
              >
                <span>Tick #{tick.seq}</span>
                <span>Value: {tick.value} {isAlert ? "(ALERT)" : ""}</span>
              </div>
            );
          })
        )}
      </div>
    </div>
  );
}

import { render, route } from "rwsdk/router";
import { defineApp } from "rwsdk/worker";
import { syncedStateRoutes } from "rwsdk/use-synced-state/worker";

import { Document } from "@/app/document";
import { setCommonHeaders } from "@/app/headers";
import { Home } from "@/app/pages/home";
import { MetricsPage } from "@/app/pages/metrics";
import { CustomSyncedStateServer } from "@/app/CustomSyncedStateServer";

export type AppContext = {};

// Export the Durable Object class so Wrangler can bind it
export { CustomSyncedStateServer };

export default defineApp([
  setCommonHeaders(),
  ...syncedStateRoutes((env: any) => env.syncedState),
  render(Document, [
    route("/", Home),
    route("/metrics", MetricsPage),
  ]),
]);

